{"command":"python3 -c "
import rdflib

g = rdflib.Graph()
g.parse('/app/university_graph.ttl', format='ttl')

print('--- ALL PROFESSORS / PEOPLE ---')
q_prof = '''
PREFIX uni: <http://university.org/ontology/>
SELECT ?p ?name ?role ?dept ?uni ?country WHERE {
    ?p a uni:Person .
    ?p uni:hasName ?name .
    OPTIONAL { ?p uni:role ?role }
    OPTIONAL { 
        ?p uni:worksIn ?dept .
        OPTIONAL {
            ?dept uni:belongsTo ?u .
            ?u uni:locatedInCountry ?country .
        }
    }
}
'''
for row in g.query(q_prof):
    print(row)
""}

