import rdflib

g = rdflib.Graph()
g.parse('/app/university_graph.ttl', format='ttl')

print('--- COURSES AND DEPARTMENTS ---')
q_courses = '''
PREFIX uni: <http://university.org/ontology/>
SELECT ?course ?dept ?u ?country WHERE {
    ?course a uni:Course .
    ?course uni:isTaughtIn ?dept .
    ?dept uni:belongsTo ?u .
    ?u uni:locatedInCountry ?country .
}
'''
for row in g.query(q_courses):
    print(row)

print('\n--- ENROLLMENTS SUMMARY ---')
q_enr = '''
PREFIX uni: <http://university.org/ontology/>
SELECT ?student ?course ?enrDate ?gradDate WHERE {
    ?student a uni:Person .
    ?student uni:isEnrolledIn ?course .
    OPTIONAL { ?student uni:hasEnrollmentDate ?enrDate }
    OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
}
'''
for row in g.query(q_enr):
    print(row)
""}

