import rdflib

g = rdflib.Graph()
g.parse('/app/university_graph.ttl', format='ttl')

print('--- ALL STUDENTS AND DATES ---')
q = '''
PREFIX uni: <http://university.org/ontology/>
SELECT ?student ?course ?enrDate ?gradDate WHERE {
    ?student a uni:Person .
    ?student uni:role \"Student\" .
    ?student uni:isEnrolledIn ?course .
    OPTIONAL { ?student uni:hasEnrollmentDate ?enrDate }
    OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
}
ORDER BY ?course ?student
'''
for row in g.query(q):
    print(row)
""}

