{"command":"python3 -c "
import rdflib

g = rdflib.Graph()
g.parse('/app/university_graph.ttl', format='ttl')

q = '''
PREFIX uni: <http://university.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?student ?enrDate ?gradDate WHERE {
    ?student uni:isEnrolledIn uni:Math201 .
    OPTIONAL { ?student uni:hasEnrollmentDate ?enrDate }
    OPTIONAL { ?student uni:hasGraduationDate ?gradDate }
}
'''

for r in g.query(q):
    st = str(r.student).split('/')[-1]
    enr = str(r.enrDate) if r.enrDate else 'None'
    grad = str(r.gradDate) if r.gradDate else 'None'
    is_current = (r.enrDate is None or str(r.enrDate) <= '2025-08-16') and (r.gradDate is None or str(r.gradDate) > '2025-08-16')
    print(f'{st:10} | enr: {enr:10} | grad: {grad:10} | CURRENT: {is_current}')
""}
